 {"sec": "Neuroblastoma work-up and management · p223–224", "page": 224, "q": "Match the neuroblastoma risk category with its features:", "opts": ["A-3, B-2, C-1, D-4", "A-2, B-3, C-4, D-1", "A-4, B-1, C-3, D-2", "A-4, B-1, C-2, D-3"], "ans": 1, "exp": "Correct pairs: Low risk (stages)→Stage I, II and 4s; High risk (stages)→Stage 3 and 4; Low-risk age of onset→< 18 months; High-risk genetics→> 18 months with hypodiploidy and N-myc amplification. (Book p224)", "type": "match", "pairs": [["Low risk (stages)", "> 18 months with hypodiploidy and N-myc amplification"], ["High risk (stages)", "Stage I, II and 4s"], ["Low-risk age of onset", "Stage 3 and 4"], ["High-risk genetics", "< 18 months"]], "id": "PEDS-C48-060"},
 {"sec": "Neuroblastoma work-up and management · p223–224", "page": 224, "q": "The treatment of localised neuroblastoma is —", "opts": ["Autologous stem cell transplant", "Surgical resection of the tumour", "Chemotherapy alone", "Radiotherapy alone"], "ans": 1, "exp": "Rx: localised → surgical resection of the tumour. (Book p224)", "type": "mcq", "id": "PEDS-C48-061"},
 {"sec": "Neuroblastoma work-up and management · p223–224", "page": 224, "q": "Disseminated neuroblastoma is treated with surgery plus chemotherapy comprising cisplatin, cyclophosphamide, vincristine and ___.", "opts": ["Actinomycin D", "Methotrexate", "Etoposide", "Doxorubicin"], "ans": 2, "exp": "Chemotherapy for disseminated disease: cisplatin, cyclophosphamide, vincristine, etoposide. (Book p224)", "type": "fill", "id": "PEDS-C48-062"},
 {"sec": "Neuroblastoma work-up and management · p223–224", "page": 224, "q": "In neuroblastoma, if there is no response to chemotherapy, the next step is —", "opts": ["Second-line platinum doublet", "Immediate autologous HSCT", "Observation", "Radiotherapy"], "ans": 3, "exp": "No response → radiotherapy; if refractory → autologous hematopoietic stem cell transplant. (Book p224)", "type": "mcq", "id": "PEDS-C48-063"},
 {"sec": "Neuroblastoma work-up and management · p223–224", "page": 224, "q": "Autologous hematopoietic stem cell transplant in neuroblastoma is offered when the disease is —", "opts": ["Refractory after radiotherapy", "Localised and resectable", "Stage 1 with hyperdiploidy", "Stage 4S in an infant"], "ans": 0, "exp": "If refractory (after no response → radiotherapy) → AHSCT. (Book p224)", "type": "mcq", "id": "PEDS-C48-064"},
