 {"sec": "Neuroblastoma work-up and management · p223–224", "page": 224, "q": "True or False — INSS stage 4S neuroblastoma carries a poor prognosis.", "opts": ["True", "False"], "ans": 1, "exp": "False — stage 4S (infant with dissemination to bone/liver/skin) carries a GOOD prognosis. (Book p223)", "type": "tf", "id": "PEDS-C48-066"},
